-- « Signature électronique » (LecteurSignatureElectronique, EcrivainSignatureElectronique), lot 10 du plan « RIG v3 100 % fonctionnel »
-- (plan-676a4b19). Identifiants 2 000 3xx, roles 2026SJ203xx. Ce qui est retenu ou ecarte, et pourquoi : PROC_SIGNJUD.attendu.
-- Ce jeu porte AUSSI les lignes de « Éditions différées » (PROC_EDT_DIFF.attendu, en fin de fichier) : elles s'appuient sur le lot Amitel
-- AMI_BANC9 et son groupe BANC9-G07 que PROC_GESTLOT.sql et PROC_RELANCELOT.sql creent, joues avant celui-ci (et apres PROC_EDT_DIFF.sql).
-- Ses demandes d'edition entrent dans « File des éditions » (PROC_POOLEDITION.attendu, qui les liste).
IF COL_LENGTH('v2.INSTANCE', 'INSTN_TYPE_INSTANCE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_TYPE_INSTANCE varchar(2) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_TOP_EXPERIAN') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_TOP_EXPERIAN bit NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_DATE_MAJ_INFOG') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_DATE_MAJ_INFOG datetime NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_ETAT_REDACTION') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_ETAT_REDACTION varchar(1) NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_ID_APPAF_PRONONCER') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_ID_APPAF_PRONONCER int NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_ID_APPAF_DELIBERER') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_ID_APPAF_DELIBERER int NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_ID_JUG') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_ID_JUG int NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_ID_GRASS') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_ID_GRASS int NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_AVEC_PIECE_NUMERISE') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_AVEC_PIECE_NUMERISE bit NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_NUMERO_SOURCE') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_NUMERO_SOURCE varchar(36) NULL;
IF COL_LENGTH('v2.TYPE_DECISION', 'R_TYPEDECISI_DECISION_AVEC_REDACTION') IS NULL ALTER TABLE v2.TYPE_DECISION ADD R_TYPEDECISI_DECISION_AVEC_REDACTION bit NULL;
IF COL_LENGTH('v2.JUGE', 'JUG_ABREGE') IS NULL ALTER TABLE v2.JUGE ADD JUG_ABREGE varchar(16) NULL;
IF COL_LENGTH('v2.JUGE', 'JUG_ADRESSE_MAIL') IS NULL ALTER TABLE v2.JUGE ADD JUG_ADRESSE_MAIL varchar(255) NULL;
IF COL_LENGTH('v2.JUGE', 'JUG_SIGNATURE_DEMAT_TYPE_INSTANCES') IS NULL ALTER TABLE v2.JUGE ADD JUG_SIGNATURE_DEMAT_TYPE_INSTANCES varchar(255) NULL;
IF OBJECT_ID(N'v2.GREFFIER_ASSERMENTE') IS NULL
    CREATE TABLE v2.GREFFIER_ASSERMENTE (GRASS_ID_GRASS int NOT NULL PRIMARY KEY, GRASS_ABREGE varchar(16) NOT NULL, GRASS_CIVILITE varchar(7) NOT NULL,
        GRASS_NOM varchar(35) NOT NULL, GRASS_PRENOM varchar(20) NULL, GRASS_ACTIF bit NOT NULL DEFAULT (1));
IF COL_LENGTH('v2.GREFFIER_ASSERMENTE', 'GRASS_ID_UTLST') IS NULL ALTER TABLE v2.GREFFIER_ASSERMENTE ADD GRASS_ID_UTLST int NULL;
IF OBJECT_ID(N'v2.DOCUMENT_DOSSIER') IS NULL
    CREATE TABLE v2.DOCUMENT_DOSSIER (DCMDS_ID_DCMDS int NOT NULL PRIMARY KEY, DCMDS_CODE_ENTITE varchar(16) NULL, DCMDS_VALEUR_ID_METIER int NULL,
        DCMDS_CODE_MODELE_DOCUMENT varchar(30) NULL, DCMDS_ID_JUG int NULL, DCMDS_ID_GRASS int NULL, DCMDS_DATE_IMPRESSION_MINUTE datetime NULL,
        DCMDS_SUPPLEMENT_GROSSE varchar(100) NOT NULL DEFAULT (''), DCMDS_SUPPLEMENT_COPIE varchar(100) NOT NULL DEFAULT (''),
        DCMDS_SUPPLEMENT_EXPEDI varchar(100) NOT NULL DEFAULT (''));
IF OBJECT_ID(N'v2.OODRIVE_DOCUMENT_SIGNE') IS NULL
    CREATE TABLE v2.OODRIVE_DOCUMENT_SIGNE (OODDS_ID_OODDS int NOT NULL PRIMARY KEY, OODDS_DATE_CREATION datetime NULL, OODDS_ETAT varchar(30) NULL,
        OODDS_NOM_FICHIER varchar(200) NULL, OODDS_GUID_DOSSIER_OO_JUGE uniqueidentifier NULL, OODDS_DATE_MAJ_JUGE datetime NULL,
        OODDS_ABREGE_JUGE varchar(32) NULL, OODDS_SIGNATURE_JUGE varchar(32) NULL, OODDS_DATE_MAJ_GREFFIER datetime NULL,
        OODDS_ABREGE_GREFFIER varchar(32) NULL, OODDS_SIGNATURE_GREFFIER varchar(32) NULL, OODDS_ID_DCJDC int NULL, OODDS_ID_INSTN int NULL,
        OODDS_MOTIF_REJET varchar(max) NULL);
IF OBJECT_ID(N'v2.OODRIVE_DOCUMENT_SIGNE_ETAT') IS NULL
    CREATE TABLE v2.OODRIVE_DOCUMENT_SIGNE_ETAT (OODDS_ETAT varchar(30) NOT NULL PRIMARY KEY, OODDS_LIBELLE varchar(100) NOT NULL);
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_NUM_GROUPE') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_NUM_GROUPE varchar(40) NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_IMPRESSION') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_IMPRESSION bit NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_CODE_ENTITE_SOURCE') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_CODE_ENTITE_SOURCE varchar(16) NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_VALEUR_ID_SOURCE') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_VALEUR_ID_SOURCE varchar(40) NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_CODE_MAQUETTE') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_CODE_MAQUETTE varchar(40) NULL;
IF COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_TYPE_DOCUMENT') IS NULL ALTER TABLE v2.DEMANDE_EDITION ADD DMNED_TYPE_DOCUMENT varchar(10) NULL;

-- Les etats Oodrive (OODRIVE_DOCUMENT_SIGNE_ETAT de RIG_DEV), le juge (mail et cle electronique pour CX, ou sans mail), deux greffiers
-- (l'utilisateur RIG v2 2000901 = l'agent du banc, soc.Compte.IdV2 ; 2000902 un autre), deux types de decision (sans redaction, avec).
EXEC sp_executesql N'
INSERT INTO v2.OODRIVE_DOCUMENT_SIGNE_ETAT (OODDS_ETAT, OODDS_LIBELLE)
SELECT e, l FROM (VALUES (''A_CORRIGER'', ''Le document doit être corrigée''), (''EN_ATTENTE'', ''Attente de signature''),
    (''EN_COURS_GREFFIER'', ''En cours de signature (Oodrive)''), (''EN_COURS_JUGE'', ''En cours de signature (Oodrive)''), (''ERREUR_AUTRE'', ''Erreur''),
    (''ERREUR_GREFFIER'', ''Erreur de signature greffier''), (''ERREUR_JUGE'', ''Erreur de signature juge''), (''SIGNE_GREFFIER'', ''Signé par le greffier''),
    (''SIGNE_JUGE'', ''Signé par le juge'')) AS x (e, l) WHERE NOT EXISTS (SELECT 1 FROM v2.OODRIVE_DOCUMENT_SIGNE_ETAT AS y WHERE y.OODDS_ETAT = x.e);
INSERT INTO v2.JUGE (JUG_ID_JUG, JUG_CIVILITE, JUG_NOM, JUG_PRENOM, JUG_ABREGE, JUG_ADRESSE_MAIL, JUG_SIGNATURE_DEMAT_TYPE_INSTANCES) VALUES
    (2000301, ''M.'', ''JUGESIGN'', ''Paul'', ''JSIGN'', ''juge.banc@greffe.test'', ''CX,RP''), (2000302, ''MME'', ''JUGESANSMAIL'', ''Lea'', ''JSANS'', NULL, ''CX'');
INSERT INTO v2.GREFFIER_ASSERMENTE (GRASS_ID_GRASS, GRASS_ABREGE, GRASS_CIVILITE, GRASS_NOM, GRASS_PRENOM, GRASS_ID_UTLST) VALUES
    (2000301, ''GSIGN'', ''M.'', ''GREFFSIGN'', ''Marc'', 2000901), (2000302, ''GAUTRE'', ''MME'', ''GREFFAUTRE'', ''Ines'', 2000902);
INSERT INTO v2.TYPE_DECISION (R_TYPEDECISI_VALEUR, R_TYPEDECISI_LIBELLE_ECRAN, R_TYPEDECISI_DECISION_AVEC_REDACTION) VALUES
    (''SJSANS20'', ''Ordonnance à signer du banc'', 0), (''SJREDA20'', ''Jugement rédigé du banc'', 1);
UPDATE soc.Compte SET IdV2 = 2000901 WHERE CompteWindows = ''banc.ecrans'' AND IdV2 IS NULL;';

-- Les instances (type CX, sans code affaire) et leurs decisions, prevues le 10/03/1990 ; juge 2000301 et greffier 2000301 sauf mention.
EXEC sp_executesql N'
INSERT INTO v2.INSTANCE (INSTN_ID_INSTN, INSTN_NUM_ROLE, INSTN_NOM_COURANT, INSTN_TYPE_INSTANCE)
SELECT n, ''2026SJ2'' + RIGHT(CONVERT(varchar(7), n), 4), ''SIGN '' + CHAR(64 + n - 2000300), ''CX'' FROM (VALUES (2000301), (2000302), (2000303), (2000304),
    (2000305), (2000306), (2000307), (2000308), (2000309), (2000310), (2000311), (2000312), (2000313)) AS x (n);
INSERT INTO v2.DECISION_JUDICIAIRE (DCJDC_ID_DCJDC, DCJDC_ID_INSTN, DCJDC_NUM_ORDRE, DCJDC_DATE_PREVUE, DCJDC_DATE, DCJDC_TYPE_DECISION, DCJDC_ETAT_REDACTION,
                                    DCJDC_ID_JUG, DCJDC_ID_GRASS, DCJDC_AVEC_PIECE_NUMERISE, DCJDC_NUMERO_SOURCE)
SELECT n, n, 1, DATEADD(day, n - 2000300, ''1990-03-09''), NULL, CASE WHEN n IN (2000311, 2000312, 2000313) THEN ''SJREDA20'' ELSE ''SJSANS20'' END,
       CASE n WHEN 2000311 THEN ''3'' WHEN 2000312 THEN ''2'' ELSE ''0'' END, CASE n WHEN 2000302 THEN 2000302 ELSE 2000301 END,
       CASE n WHEN 2000307 THEN 2000302 ELSE 2000301 END, CASE WHEN n = 2000307 THEN 1 WHEN n = 2000306 THEN 1 ELSE 0 END,
       ''00000000-0000-0000-0000-00000'' + CONVERT(varchar(7), n)
FROM (VALUES (2000301), (2000302), (2000303), (2000304), (2000305), (2000306), (2000307), (2000308), (2000309), (2000310), (2000311), (2000312), (2000313)) AS x (n);';

-- Le document REDA de 2000311 (etat 3, signable) et de 2000312 (etat 2, pas encore). Les lignes Oodrive : 2000303 a corriger, 2000304 et
-- 2000305 chez le juge (meme dossier Oodrive), 2000306 et 2000307 signees par le juge, 2000308 contresignee le jour du banc, 2000309 l'an
-- dernier, 2000310 en erreur. Une edition hors REDA de la decision pour 2000301, 2000302 et 2000303 (emise, sans date).
EXEC sp_executesql N'
INSERT INTO v2.DOCUMENT_DOSSIER (DCMDS_ID_DCMDS, DCMDS_CODE_ENTITE, DCMDS_VALEUR_ID_METIER, DCMDS_CODE_MODELE_DOCUMENT, DCMDS_ID_JUG, DCMDS_ID_GRASS) VALUES
    (2000311, ''REDA_DECI_JUD'', 2000311, ''MODSJ20'', 2000301, 2000301), (2000312, ''REDA_DECI_JUD'', 2000312, ''MODSJ20'', 2000301, 2000301);
INSERT INTO v2.OODRIVE_DOCUMENT_SIGNE (OODDS_ID_OODDS, OODDS_DATE_CREATION, OODDS_ETAT, OODDS_GUID_DOSSIER_OO_JUGE, OODDS_DATE_MAJ_GREFFIER, OODDS_ID_DCJDC, OODDS_ID_INSTN, OODDS_MOTIF_REJET) VALUES
    (2000303, ''2026-01-03'', ''A_CORRIGER'', NULL, NULL, 2000303, 2000303, ''Mauvaise date''),
    (2000304, ''2026-01-04'', ''EN_ATTENTE'', ''00000000-0000-0000-0000-000002000304'', NULL, 2000304, 2000304, NULL),
    (2000305, ''2026-01-04'', ''EN_COURS_JUGE'', ''00000000-0000-0000-0000-000002000304'', NULL, 2000305, 2000305, NULL),
    (2000306, ''2026-01-06'', ''SIGNE_JUGE'', NULL, NULL, 2000306, 2000306, NULL),
    (2000307, ''2026-01-07'', ''SIGNE_JUGE'', NULL, NULL, 2000307, 2000307, NULL),
    (2000308, ''2026-01-08'', ''SIGNE_GREFFIER'', NULL, @aujourdhui, 2000308, 2000308, NULL),
    (2000309, ''2025-01-09'', ''SIGNE_GREFFIER'', NULL, DATEADD(year, -1, @aujourdhui), 2000309, 2000309, NULL),
    (2000310, ''2026-01-10'', ''ERREUR_JUGE'', NULL, NULL, 2000310, 2000310, NULL);
', N'@aujourdhui datetime', @aujourdhui;
-- Les editions : avec les colonnes NOT NULL sans defaut de la base V3 (DMNED_HAS_NUMLRAR..., posees par PROC_REGJUD.sql) a 0, comme
-- PROC_RELANCELOT.sql. 2000301 a 2000303 : une edition hors REDA de chaque decision ; 2000304 : celle du groupe BANC10-G01 (en fin de fichier).
DECLARE @colonnes nvarchar(200) = CASE WHEN COL_LENGTH('v2.DEMANDE_EDITION', 'DMNED_MASQUER_COFFRE_FORT') IS NULL THEN N'' ELSE N', DMNED_HAS_NUMLRAR, DMNED_IS_NON_SUPPRESSIBLE, DMNED_HAS_NUMLR, DMNED_MASQUER_COFFRE_FORT' END;
DECLARE @zeros nvarchar(50) = CASE WHEN @colonnes = N'' THEN N'' ELSE N', 0, 0, 0, 0' END;
DECLARE @sql nvarchar(max) = N'INSERT INTO v2.DEMANDE_EDITION (DMNED_ID_DMNED, DMNED_PHASE_TRAITEMENT, DMNED_LIBELLE_DOCUMENT, DMNED_CODE_ENTITE_SOURCE, DMNED_VALEUR_ID_SOURCE, DMNED_CODE_MAQUETTE' + @colonnes + N')
SELECT n, ''E'', ''Ordonnance du banc 10'', ''DECI_JUDICIAIRE'', ''00000000-0000-0000-0000-00000'' + CONVERT(varchar(7), n), ''OS20''' + @zeros + N' FROM (VALUES (2000301), (2000302), (2000303)) AS x (n);';
EXEC sp_executesql @sql;

-- « Éditions différées » (PROC_EDT_DIFF.attendu) : le lot Amitel AMI_BANC9 (PROC_GESTLOT.sql) devient visible des editions differees ; son
-- groupe BANC9-G07 (PROC_RELANCELOT.sql : emis, 1 edition, sans date de fin, imprimante « Imprimante Amitel ») est a cloturer. Deux groupes
-- de plus : BANC10-G01 sans imprimante (une edition « ne pas imprimer »), BANC10-G02 sans edition (ecarte : « having count > 0 »). La
-- liste de « Relancer un lot » ecarte les files Amitel : ces groupes n'y entrent pas.
UPDATE v2.LOT SET LOT_VISIBLE_EDTDIFF = 1 WHERE LOT_NOM = 'AMI_BANC9';
INSERT INTO v2.GROUPE_IMPRESSION (GPIMP_NUM_GROUPE, GPIMP_NOM_LOT, GPIMP_DATE_DEBUT, GPIMP_DATE_FIN, GPIMP_NOM_IMPRIMANTE, GPIMP_PHASE_TRAITEMENT) VALUES
    ('BANC10-G01', 'AMI_BANC9', DATEADD(day, -2, @aujourdhui), NULL, NULL, 'I'),
    ('BANC10-G02', 'AMI_BANC9', DATEADD(day, -2, @aujourdhui), NULL, 'Imprimante banc 10', 'I');
SET @sql = N'INSERT INTO v2.DEMANDE_EDITION (DMNED_ID_DMNED, DMNED_PHASE_TRAITEMENT, DMNED_LIBELLE_DOCUMENT, DMNED_LOT, DMNED_NUM_GROUPE, DMNED_IMPRESSION' + @colonnes + N')
VALUES (2000304, ''E'', ''Courrier différé du banc 10'', ''AMI_BANC9'', ''BANC10-G01'', 0' + @zeros + N');';
EXEC sp_executesql @sql;
EXEC sp_executesql N'
IF NOT EXISTS (SELECT 1 FROM v2.IMPRIMANTE_EDITION WHERE IMPED_NOM_LOGIQUE = ''Imprimante Amitel'')
    INSERT INTO v2.IMPRIMANTE_EDITION (IMPED_NOM_LOGIQUE, IMPED_NOM_PHYSIQUE, IMPED_ONLY_AMITEL) VALUES (''Imprimante Amitel'', ''RL'', 1);';
